import { Collapsible } from "@base-ui/react/collapsible";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { CheckIcon } from "lucide-react";
import type * as React from "react";

/** 展开区的一段：标签 + 等宽正文。 */
interface AgentStepSection {
  label: string;
  body: string;
}

const agentStepLabelVariants = cva("min-w-0 truncate font-medium", {
  variants: {
    tone: {
      default: "text-foreground",
      muted: "text-muted-foreground",
    },
  },
  defaultVariants: {
    tone: "default",
  },
});

/**
 * Collapsible.Root 在面板开合时也渲染 data-starting-style／data-ending-style。根元素带着入场预设（data-motion），
 * 这两个属性会让它在收起时按离场预设淡出、下移。根元素只要挂载时的入场，所以渲染时去掉它们。
 */
function RootWithoutTransitionStyle({
  "data-starting-style": _starting,
  "data-ending-style": _ending,
  ...props
}: React.ComponentProps<"div"> & {
  "data-starting-style"?: unknown;
  "data-ending-style"?: unknown;
}) {
  return <div {...props} />;
}

/**
 * 轨迹里一步的动效预设（ADR 0021）。缺省 `slide-up`。
 * - `slide-up`：挂载时从下方 16px 升起并淡入，220ms。流式追加的步骤。
 * - `fade`：挂载时只淡入，150ms。一次渲染整条轨迹时。
 * - `none`：直接出现。
 */
type AgentStepMotion = "none" | "fade" | "slide-up";

/** 轨迹里的一步：折叠态一行（图标 + 截断文本），有明细时点开看全文。 */
function AgentStep({
  label,
  icon,
  detail,
  tone = "default",
  motion = "slide-up",
  className,
  children,
  ...props
}: Omit<Collapsible.Root.Props, "children" | "className"> &
  VariantProps<typeof agentStepLabelVariants> & {
    label: React.ReactNode;
    /** lucide 图标元素，默认 CheckIcon。 */
    icon?: React.ReactNode;
    /** 点开后的段落；空数组且没有 children 时不可展开。 */
    detail?: AgentStepSection[];
    motion?: AgentStepMotion;
    className?: string;
    children?: React.ReactNode;
  }) {
  const expandable = Boolean(detail?.length) || Boolean(children);
  return (
    <Collapsible.Root
      data-slot="agent-step"
      data-tone={tone}
      data-motion={motion === "none" ? undefined : motion}
      render={(rootProps) => <RootWithoutTransitionStyle {...rootProps} />}
      disabled={!expandable}
      className={cn("group/agent-step min-w-0", className)}
      {...props}
    >
      <Collapsible.Trigger
        data-slot="agent-step-trigger"
        className="flex min-h-7 w-full items-center gap-2 rounded-none px-1.5 py-0.5 text-left text-xs outline-none transition-colors duration-100 not-data-disabled:hover:bg-muted focus-visible:ring-1 focus-visible:ring-ring/50 data-disabled:cursor-default [&_svg]:pointer-events-none [&_svg]:size-3.5 [&_svg]:shrink-0 [&_svg]:text-muted-foreground"
      >
        {icon ?? <CheckIcon aria-hidden="true" />}
        <span className={agentStepLabelVariants({ tone })}>{label}</span>
      </Collapsible.Trigger>
      {/* 展开收起用预设 expand：高度取 Base UI 的 --collapsible-panel-height，展开 ease-enter，收起 ease-exit。 */}
      <Collapsible.Panel data-slot="agent-step-panel" data-motion="expand">
        <div className="mt-0.5 mb-1 ml-2 flex min-w-0 flex-col gap-1 border-l border-border py-0.5 pl-3.5">
          {children}
          {detail?.map((section) => (
            <div data-slot="agent-step-section" className="min-w-0" key={section.label}>
              <div className="text-xs text-muted-foreground">{section.label}</div>
              <pre className="mt-0.5 max-h-72 overflow-auto rounded-none bg-muted p-1.5 font-mono text-xs break-all whitespace-pre-wrap text-muted-foreground">
                {section.body}
              </pre>
            </div>
          ))}
        </div>
      </Collapsible.Panel>
    </Collapsible.Root>
  );
}

/** 嵌套在其它步骤下的推理文本；每个子元素一行，超长截断。 */
function AgentReasoning({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="agent-reasoning"
      className={cn(
        "mt-0.5 mb-1 ml-2 flex min-w-0 flex-col gap-0.5 border-l border-border py-0.5 pl-3.5 text-xs leading-relaxed text-muted-foreground *:truncate",
        className,
      )}
      {...props}
    />
  );
}

export { AgentReasoning, AgentStep, type AgentStepMotion, type AgentStepSection };

"use client";

/**
 * 移植自 Beautiful UI（https://www.beautifului.dev/）的 Task Rows 原语，经 logwingspider 转手，
 * 按 #16 Q13 改造：令牌换成 shadcn 语义令牌与状态色，API 改成系统风格（data-slot、透传 className、
 * 展开态可受控、cva），展开收起由 Base UI Collapsible 承担，运行中的流光用基础层的 animate-shimmer，
 * 刻度跟 Lyra（rounded-none、text-xs、ring-1）。
 * 动效由 `motion` 属性选预设（ADR 0021）：一行挂载时入场，缺省 `slide-up`；明细面板固定用 `expand`。
 * 状态圆点不再单独弹入（原来的 zoom-in-50）：它随整行一起入场，两层都动是噪音。
 * 汇总见仓库根 THIRD_PARTY_NOTICES.md。原许可证如下：
