import { Collapsible } from "@base-ui/react/collapsible";
import { cva } from "class-variance-authority";
import { cn } from "cn";
import { CheckIcon, XIcon } from "lucide-react";
import type * as React from "react";

type AgentTaskStatus = "ok" | "fail" | "running";

/** 圆点是纯视觉的成败信号，屏幕阅读器读这句。 */
const STATUS_LABEL: Record<AgentTaskStatus, string> = {
  ok: "全部成功",
  fail: "有失败",
  running: "进行中",
};

const agentTaskDotVariants = cva(
  "flex size-5.5 shrink-0 items-center justify-center rounded-full [&_svg]:size-3.5 [&_svg]:stroke-3",
  {
    variants: {
      status: {
        ok: "bg-success text-success-foreground",
        fail: "bg-destructive text-destructive-foreground",
        running: "bg-muted text-muted-foreground",
      },
    },
  },
);

const agentTaskTitleVariants = cva("min-w-0 flex-1 truncate font-medium", {
  variants: {
    status: {
      ok: "text-foreground",
      fail: "text-foreground",
      // 流光配方见 @developstack/tokens/base.css 的 @keyframes shimmer 注释。
      running:
        "animate-shimmer bg-linear-to-r from-muted-foreground from-35% via-foreground via-50% to-muted-foreground to-65% bg-clip-text text-transparent",
    },
  },
});

/**
 * Collapsible.Root 在面板开合时也渲染 data-starting-style／data-ending-style。根元素带着入场预设（data-motion），
 * 这两个属性会让它在收起时按离场预设淡出、下移。根元素只要挂载时的入场，所以渲染时去掉它们。
 */
function RootWithoutTransitionStyle({
  "data-starting-style": _starting,
  "data-ending-style": _ending,
  ...props
}: React.ComponentProps<"div"> & {
  "data-starting-style"?: unknown;
  "data-ending-style"?: unknown;
}) {
  return <div {...props} />;
}

/**
 * 任务行的动效预设（ADR 0021）。缺省 `slide-up`。
 * - `slide-up`：挂载时从下方 16px 升起并淡入，220ms。新开始的一轮。
 * - `fade`：挂载时只淡入，150ms。一次渲染很多轮（加载历史）时。
 * - `none`：直接出现。
 */
type AgentTaskRowMotion = "none" | "fade" | "slide-up";

/** 一个可展开的任务行卡片（一个 turn 一张）。折叠态高 44px，展开后是明细区。 */
function AgentTaskRow({
  title,
  metrics,
  status = "ok",
  motion = "slide-up",
  className,
  children,
  ...props
}: Omit<Collapsible.Root.Props, "children" | "className" | "title"> & {
  title: React.ReactNode;
  /** 右侧的等宽指标，如耗时、token 数。 */
  metrics?: React.ReactNode;
  status?: AgentTaskStatus;
  motion?: AgentTaskRowMotion;
  className?: string;
  children?: React.ReactNode;
}) {
  return (
    <Collapsible.Root
      data-slot="agent-task-row"
      data-status={status}
      data-motion={motion === "none" ? undefined : motion}
      render={(rootProps) => <RootWithoutTransitionStyle {...rootProps} />}
      disabled={!children}
      className={cn(
        "group/agent-task-row min-w-0 self-stretch overflow-hidden rounded-none bg-card text-xs text-card-foreground ring-1 ring-foreground/10 hover:bg-muted/50",
        className,
      )}
      {...props}
    >
      <Collapsible.Trigger
        data-slot="agent-task-row-trigger"
        className="flex h-11 w-full items-center gap-2.5 px-2.5 text-left outline-none focus-visible:ring-1 focus-visible:ring-ring/50 focus-visible:ring-inset data-disabled:cursor-default"
      >
        <span className="flex size-6 shrink-0 items-center justify-center">
          <span data-slot="agent-task-row-dot" className={agentTaskDotVariants({ status })}>
            {status === "ok" ? <CheckIcon aria-hidden="true" /> : null}
            {status === "fail" ? <XIcon aria-hidden="true" /> : null}
          </span>
          <span className="sr-only">{STATUS_LABEL[status]}</span>
        </span>
        <span
          data-slot="agent-task-row-title"
          role={status === "running" ? "status" : undefined}
          className={agentTaskTitleVariants({ status })}
        >
          {title}
        </span>
        {metrics ? (
          <span className="shrink-0 font-mono text-muted-foreground tabular-nums">{metrics}</span>
        ) : null}
      </Collapsible.Trigger>
      {/* 展开收起用预设 expand：高度取 Base UI 的 --collapsible-panel-height，展开 ease-enter，收起 ease-exit。 */}
      <Collapsible.Panel data-slot="agent-task-row-panel" data-motion="expand">
        <div className="mb-2.5 flex gap-2.5 px-2.5">
          <span aria-hidden="true" className="flex w-6 shrink-0 justify-center">
            <span className="w-px bg-border" />
          </span>
          <div className="flex min-w-0 flex-1 flex-col gap-1.5 pb-1">{children}</div>
        </div>
      </Collapsible.Panel>
    </Collapsible.Root>
  );
}

export { AgentTaskRow, type AgentTaskRowMotion, type AgentTaskStatus };
